"""Native paired mouth bridge for explicitly grouped original carriageways.

Outer corners remain the existing fixed-radius curve construction. The one
side inside a paired connector is a plateau between the two inner mouth ends,
not another road corner. This primitive currently rejects overlapping mouth
intervals; a dynamic pavement-union mouth is a separate construction.
"""
import bpy
from . import curved_corner_nodes as c


def approach(*,interpolation=False):
    from . import curved_port_nodes
    original=curved_port_nodes.approach(interpolation=interpolation)
    name='Prochitecture Streets / Aggregate path view v1'+(' / Modes' if interpolation else '')
    if name in bpy.data.node_groups:return bpy.data.node_groups[name]
    g=c.Graph(name)
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET':
            g.socket(socket.name,socket.socket_type,socket.in_out,default=getattr(socket,'default_value',None))
    inp=g.node('NodeGroupInput');out=g.node('NodeGroupOutput')
    at=c.V(g,inp.outputs['Index']);rows=inp.outputs['Approaches']
    kind=c._read(g,rows,'st_pp_kind',at,'INT')
    valid=g.math('COMPARE',kind,4.)
    # Only the shared path reader sees a terminal-view code. Aggregate
    # ownership and partner identities remain in the original private table.
    terminal=c._store(g,rows,'st_pp_kind',0,'INT')
    node=g.node('GeometryNodeGroup','Read the unchanged whole Street path');node.node_tree=original
    for key in ('Sources','Mapping','Index'):g.bind(inp.outputs[key],node.inputs[key])
    g.bind(terminal,node.inputs['Approaches'])
    for socket in original.interface.items_tree:
        if socket.item_type=='SOCKET' and socket.in_out=='OUTPUT':
            value=node.outputs[socket.name]
            if socket.name=='Valid':value=c.V(g,value)*valid
            g.bind(value,out.inputs[socket.name])
    return g.g


def registry(g,rows):
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);n=c._count(g,rows)
    partner=c.named(g,'st_ag_partner','INT');half=c.named(g,'st_cj_half','INT')
    paired=g.math('GREATER_THAN',partner,-.5);bridge=c.named(g,'st_ag_bridge','BOOLEAN')
    equal=lambda a,b:g.math('COMPARE',a,b)
    good=equal(c.named(g,'st_pp_kind','INT'),4.)
    for name,kind in (('st_ag_partner','INT'),('st_ag_bridge','BOOLEAN')):
        attr=g.node('GeometryNodeInputNamedAttribute');attr.data_type=kind;attr.inputs['Name'].default_value=name
        good*=c.V(g,attr.outputs['Exists'])
    pair_ok=g.math('LESS_THAN',partner,n-.5)*equal(c._read(g,rows,'st_ag_partner',partner,'INT'),i)
    pair_ok*=equal(c._read(g,rows,'st_cj_half',partner,'INT'),-half)
    pair_ok*=equal(partner,c.choose(g,bridge,i+1.,i-1.))
    pair_ok*=equal(half,c.choose(g,bridge,-1.,1.))
    for key,kind in (('bundle_id','INT'),('connector_id','INT'),('junction_id','INT'),('rise','FLOAT'),('datum','FLOAT')):
        pair_ok*=equal(c.named(g,'st_cj_'+key,kind),c._read(g,rows,'st_cj_'+key,partner,kind))
    pair_ok*=g.math('GREATER_THAN',c.named(g,'st_cj_bundle_id','INT'),-.5)
    pair_ok*=1.-equal(c.named(g,'st_cj_street_id','INT'),c._read(g,rows,'st_cj_street_id',partner,'INT'))
    ordinary=equal(partner,-1.)*equal(half,0.)*equal(c.named(g,'st_cj_bundle_id','INT'),-1.)*(1.-bridge)
    good*=c.choose(g,paired,pair_ok,ordinary)
    good*=equal(c.named(g,'st_cj_junction_id','INT'),c._read(g,rows,'st_cj_junction_id',0,'INT'))
    return c._stat(g,rows,good)*g.math('GREATER_THAN',n-c._stat(g,rows,bridge,'Sum'),2.5)


def placeholder(g,rows,at,roots):
    use=c._read(g,rows,'st_ag_bridge',at,'BOOLEAN')
    record=c._line(g,1)
    for key,value,kind in (('st_cc_sa',0.,'FLOAT'),('st_cc_sb',0.,'FLOAT'),
                           ('st_cc_radius',0.,'FLOAT'),('st_cc_sweep',0.,'FLOAT'),('st_ct_kind',1,'INT')):
        record=c._store(g,record,key,value,kind)
    return use,c.choose(g,use,record,roots,'GEOMETRY')


def finish(g,rows,corners,mouths,*,interpolation=False):
    """Resolve the plateau only after the real outer-corner cuts are known."""
    i=c.V(g,g.node('GeometryNodeInputIndex').outputs[0]);n=c._count(g,mouths)
    nxt=g.math('MODULO',i+1.,n);use=c._read(g,rows,'st_ag_bridge',i,'BOOLEAN')
    points=[];tangents=[]
    for at,side in ((i,-1.),(nxt,1.)):
        center=c._vec(g,c._read(g,mouths,'st_cj_position',at,'FLOAT_VECTOR'))
        tangent=c._vec(g,c._read(g,mouths,'st_cj_tangent',at,'FLOAT_VECTOR'));tangents.append(tangent)
        axis=c._right(tangent)
        if interpolation:
            exact=c._read(g,mouths,'st_cj_polyline',at,'BOOLEAN')
            axis=c._pick(g,exact,c._vec(g,c._read(g,mouths,'st_cj_profile_axis',at,'FLOAT_VECTOR')),axis)
        points.append(c._add(center,c._scale(axis,side*.5*c._read(g,mouths,'st_cj_width',at))))
    delta=c._sub(points[1],points[0]);gap_ok=1.
    for tangent in tangents:
        gap=c._dot(delta,c._scale(c._right(tangent),-1.))
        gap_ok*=1.-g.math('LESS_THAN',gap,0.)
    valid=c._stat(g,corners,c.choose(g,use,gap_ok,1.))
    fields=(('st_cc_sa',c._read(g,mouths,'st_cj_parameter',i),'FLOAT'),
            ('st_cc_sb',c._read(g,mouths,'st_cj_parameter',nxt),'FLOAT'),
            ('st_cc_contact_a',g.xyz(*points[0]),'FLOAT_VECTOR'),
            ('st_cc_contact_b',g.xyz(*points[1]),'FLOAT_VECTOR'),
            ('st_cc_radius',0.,'FLOAT'),('st_cc_sweep',0.,'FLOAT'),('st_ct_kind',1,'INT'))
    for key,value,kind in fields:
        corners=c._store(g,corners,key,c.choose(g,use,value,c.named(g,key,kind),
                         'VECTOR' if kind=='FLOAT_VECTOR' else kind),kind)
    corners=c._store(g,corners,'st_ag_bridge',use,'BOOLEAN')
    return corners,valid
